"607911", "type_hygro": "B", "conditionnement": "kit (groupe + bouches)", "gamme": "Milieu de gamme", "classe_energetique": "B", "source_tarifs": "Catalogue partenaire — liste fournie le 23/10/2026", "fiche_cee": "BAR-TH-127", "aides_a_verifier": true}, "description": "S&P · VMC simple flux hygroréglable · kit (groupe + bouches) · hygro B · Milieu de gamme · classe B."}, {"nom": "Kit VMC simple flux hygroréglable S&P OCTEO HYGRO ST — groupe et 3 bouches hygroréglables, réf. 607711", "nom_brut": false, "marque": "S&P", "reference": "SP-OCTEO-HYGRO-ST-KIT-607711", "aliases": [], "prix_unitaire_ht": 435.0, "unite": "unite", "fiche_cee": "BAR-TH-127", "eligible_cee": true, "eligible_mpr": false, "caracteristiques": {"type_flux": "simple", "code_article": "607711", "conditionnement": "kit (groupe + bouches)", "gamme": "Milieu de gamme", "source_tarifs": "Catalogue partenaire — liste fournie le 23/10/2026", "fiche_cee": "BAR-TH-127", "aides_a_verifier": true}, "description": "S&P · VMC simple flux hygroréglable · kit (groupe + bouches) · Milieu de gamme."}, {"nom": "VMC simple flux hygroréglable S&P OCTEO HYGRO ST — groupe seul, réf. 607700", "nom_brut": false, "marque": "S&P", "reference": "SP-OCTEO-HYGRO-ST-607700", "aliases": [], "prix_unitaire_ht": 210.0, "unite": "unite", "fiche_cee": "BAR-TH-127", "eligible_cee": true, "eligible_mpr": false, "caracteristiques": {"type_flux": "simple", "code_article": "607700", "conditionnement": "groupe seul", "gamme": "Milieu de gamme", "source_tarifs": "Catalogue partenaire — liste fournie le 23/10/2026", "fiche_cee": "BAR-TH-127", "aides_a_verifier": true}, "description": "S&P · VMC simple flux hygroréglable · groupe seul · Milieu de gamme."}, {"nom": "VMC double flux très haute efficacité Nather OPTIMEA — centrale livrée avec 2 silencieux, réf. 990642", "nom_brut": false, "marque": "Nather", "reference": "NATHER-OPTIMEA-990642", "aliases": [], "prix_unitaire_ht": 3895.39, "unite": "unite", "fiche_cee": "BAR-TH-125", "eligible_cee": true, "eligible_mpr": false, "caracteristiques": {"type_flux": "double", "code_article": "990642", "gamme": "Haut de gamme", "classe_energetique": "A", "source_tarifs": "Catalogue partenaire — liste fournie le 23/10/2026", "fiche_cee": "BAR-TH-125", "aides_a_verifier": true}, "description": "Nather · VMC double flux · Haut de gamme · classe A."}, {"nom": "VMC double flux haut rendement Atlantic Optimocosy HR Access — réf. 412258", "nom_brut": false, "marque": "Atlantic", "reference": "ATLANTIC-OPTIMOCOSY-ACCESS-412258", "aliases": [], "prix_unitaire_ht": 3306.67, "unite": "unite", "fiche_cee": "BAR-TH-125", "eligible_cee": true, "eligible_mpr": false, "caracteristiques": {"type_flux": "double", "code_article": "412258", "gamme": "Haut de gamme", "classe_energetique": "A", "source_tarifs": "Catalogue partenaire — liste fournie le 23/10/2026", "fiche_cee": "BAR-TH-125", "aides_a_verifier": true}, "description": "Atlantic · VMC double flux · Haut de gamme · classe A."}, {"nom": "VMC double flux haut rendement Atlantic Optimocosy HR Plus avec sonde CO2 — réf. 412259", "nom_brut": false, "marque": "Atlantic", "reference": "ATLANTIC-OPTIMOCOSY-PLUS-412259", "aliases": [], "prix_unitaire_ht": 4006.67, "unite": "unite", "fiche_cee": "BAR-TH-125", "eligible_cee": true, "eligible_mpr": false, "caracteristiques": {"type_flux": "double", "code_article": "412259", "gamme": "Haut de gamme", "classe_energetique": "A+", "source_tarifs": "Catalogue partenaire — liste fournie le 23/10/2026", "fiche_cee": "BAR-TH-125", "aides_a_verifier": true}, "description": "Atlantic · VMC double flux · Haut de gamme · classe A+."}]$produits$::jsonb) LOOP
    v_aliases := ARRAY(SELECT jsonb_array_elements_text(p->'aliases'));

    SELECT id INTO v_id
    FROM public.catalogue_produits
    WHERE entreprise_id = v_entreprise
      AND (reference = p->>'reference' OR reference = ANY(v_aliases))
    ORDER BY (reference = p->>'reference') DESC, actif DESC, created_at NULLS LAST
    LIMIT 1;

    IF v_id IS NULL THEN
      INSERT INTO public.catalogue_produits (
        entreprise_id, categorie, nom, marque, reference, description, caracteristiques,
        prix_unitaire_ht, unite, tva_taux, eligible_mpr, eligible_cee, fiche_cee, actif,
        public_cible, catalogue_groupe, forfait_pose_ht, forfait_evacuation_ht
      ) VALUES (
        v_entreprise, 'vmc', p->>'nom', COALESCE(p->>'marque', ''), p->>'reference',
        COALESCE(p->>'description', ''), COALESCE(p->'caracteristiques', '{}'::jsonb),
        COALESCE(NULLIF(p->>'prix_unitaire_ht', '')::numeric, 0),
        COALESCE(p->>'unite', 'unite'), 5.5,
        COALESCE((p->>'eligible_mpr')::boolean, false), COALESCE((p->>'eligible_cee')::boolean, false),
        COALESCE(p->>'fiche_cee', ''), true, 'particulier', 'particulier', 0, 0
      );
      v_ajoutes := v_ajoutes + 1;
    ELSE
      UPDATE public.catalogue_produits SET
        categorie = 'vmc',
        nom = CASE WHEN COALESCE((p->>'nom_brut')::boolean, false) THEN nom ELSE p->>'nom' END,
        marque = COALESCE(NULLIF(p->>'marque', ''), marque),
        reference = p->>'reference',
        description = CASE
          WHEN COALESCE(btrim(description), '') = ''
            OR description = nom
            OR description = p->>'nom'
          THEN p->>'description'
          ELSE description
        END,
        caracteristiques = (COALESCE(caracteristiques, '{}'::jsonb) - 'prix_a_renseigner'::text)
                           || ((p->'caracteristiques') - 'prix_a_renseigner'::text)
                           || CASE WHEN array_length(v_aliases, 1) > 0 AND reference = ANY(v_aliases)
                                THEN jsonb_build_object('ancienne_reference', reference)
                                ELSE '{}'::jsonb END,
        prix_unitaire_ht = COALESCE(NULLIF(p->>'prix_unitaire_ht', '')::numeric, prix_unitaire_ht),
        tva_taux = 5.5,
        eligible_mpr = COALESCE((p->>'eligible_mpr')::boolean, false),
        eligible_cee = COALESCE((p->>'eligible_cee')::boolean, false),
        fiche_cee = COALESCE(p->>'fiche_cee', ''),
        actif = true
      WHERE id = v_id;
      v_maj := v_maj + 1;
    END IF;

    -- Autres lignes portant l'ancienne référence (doublons probables) : laissées actives, à confirmer.
    IF array_length(v_aliases, 1) > 0 THEN
      SELECT v_doublons + count(*) INTO v_doublons
      FROM public.catalogue_produits
      WHERE entreprise_id = v_entreprise AND reference = ANY(v_aliases) AND id <> COALESCE(v_id, '00000000-0000-0000-0000-000000000000'::uuid);
    END IF;
    v_id := NULL;
  END LOOP;

  -- Drapeau « prix à renseigner » aligné sur le prix réellement présent.
  UPDATE public.catalogue_produits
  SET caracteristiques = CASE
    WHEN COALESCE(prix_unitaire_ht, 0) > 0 THEN caracteristiques - 'prix_a_renseigner'::text
    ELSE caracteristiques || '{"prix_a_renseigner": true}'::jsonb
